precision highp float;
layout(std140) uniform CCGlobal {
  highp   vec4 cc_time;
  mediump vec4 cc_screenSize;
  mediump vec4 cc_nativeSize;
  mediump vec4 cc_probeInfo;
  mediump vec4 cc_debug_view_mode;
};
layout(std140) uniform CCCamera {
  highp   mat4 cc_matView;
  highp   mat4 cc_matViewInv;
  highp   mat4 cc_matProj;
  highp   mat4 cc_matProjInv;
  highp   mat4 cc_matViewProj;
  highp   mat4 cc_matViewProjInv;
  highp   vec4 cc_cameraPos;
  mediump vec4 cc_surfaceTransform;
  mediump vec4 cc_screenScale;
  mediump vec4 cc_exposure;
  mediump vec4 cc_mainLitDir;
  mediump vec4 cc_mainLitColor;
  mediump vec4 cc_ambientSky;
  mediump vec4 cc_ambientGround;
  mediump vec4 cc_fogColor;
  mediump vec4 cc_fogBase;
  mediump vec4 cc_fogAdd;
  mediump vec4 cc_nearFar;
  mediump vec4 cc_viewPort;
};
in vec4 color;
in vec2 uv0;
layout(std140) uniform Constant {
  vec4 mainColor;
  vec4 params;
};
#define TAU 6.28318530718
float glowLine(float v, float t, float w){ return w / max(abs(v - t), 0.0008); }
float hash21(vec2 p){
  p = fract(p * vec2(123.34, 456.21));
  p += dot(p, p + 45.32);
  return fract(p.x * p.y);
}
float vnoise(vec2 p){
  vec2 i = floor(p), f = fract(p);
  vec2 u = f*f*(3.0-2.0*f);
  return mix(mix(hash21(i),              hash21(i+vec2(1.0,0.0)), u.x),
             mix(hash21(i+vec2(0.0,1.0)), hash21(i+vec2(1.0,1.0)), u.x), u.y);
}
float fbm(vec2 p){
  float v=0.0, a=0.5;
  for(int i=0;i<3;i++){ v += a*vnoise(p); p*=2.0; a*=0.5; }
  return v;
}
float voro(vec2 p, float t){
  vec2 i=floor(p), f=fract(p);
  float md=1.0;
  for(int y=-1;y<=1;y++){
    for(int x=-1;x<=1;x++){
      vec2 g=vec2(float(x),float(y));
      vec2 o=vec2(hash21(i+g), hash21(i+g+7.1));
      o=0.5+0.5*sin(t + TAU*o);
      md=min(md, length(g+o-f));
    }
  }
  return md;
}
vec2 polarTileLocal(vec2 p, float n, float rotation){
  float cR=cos(rotation), sR=sin(rotation);
  p = mat2(cR,-sR,sR,cR)*p;
  float a = atan(p.y, p.x);
  float ca = TAU/n;
  float idx = floor(a/ca + 0.5);
  float c=cos(-idx*ca), s=sin(-idx*ca);
  return mat2(c,-s,s,c)*p;
}
vec3 ACES(vec3 x){
  const float a=2.51, b=0.03, c=2.43, d=0.59, e=0.14;
  return clamp((x*(a*x+b))/(x*(c*x+d)+e), 0.0, 1.0);
}
float sdEqTri(vec2 p, float r){
  const float k = 1.7320508;
  p.x = abs(p.x) - r;
  p.y = p.y + r/k;
  if (p.x + k*p.y > 0.0) p = vec2(p.x - k*p.y, -k*p.x - p.y)/2.0;
  p.x -= clamp(p.x, -2.0*r, 0.0);
  return -length(p)*sign(p.y);
}
const vec3 C_VIOLET = vec3(0.55,0.42,0.95);
const vec3 C_PINK   = vec3(1.00,0.60,0.80);
const vec3 C_ROSE   = vec3(1.00,0.42,0.66);
const vec3 C_WHITE  = vec3(1.00,0.92,0.97);
const vec3 C_GOLD   = vec3(0.97,0.82,0.55);
vec3 scene(vec2 p, float t){
  float r = length(p);
  float a = atan(p.y, p.x);
  float bloom = params.y;
  float rs    = params.x;
  vec3 col = vec3(0.0);
  vec2 q = p*2.2;
  q += 0.45*vec2(fbm(p*2.0 + t*0.05), fbm(p*2.0 - t*0.04));
  float neb = fbm(q + t*0.03);
  col += mix(C_VIOLET, C_PINK, neb) * neb * 0.22 * smoothstep(1.25,0.10,r);
  float vd = voro(p*(5.0+params.w*3.0), t*0.3);
  float stars = smoothstep(0.085, 0.0, vd);
  col += C_WHITE * stars * 0.5 * (0.4+0.6*sin(t*3.0 + r*18.0));
  float pulse = glowLine(r, fract(t*0.18), bloom*0.5) * smoothstep(1.05,0.15,r);
  col += C_PINK * pulse * 0.16;
  float br0 = 0.5+0.5*sin(t*1.1);
  col += mix(C_PINK,C_ROSE,0.5) * (glowLine(r,0.82+0.012*br0,bloom)+glowLine(r,0.79,bloom*0.55))*0.5;
  {
    float dots = glowLine(fract((a + t*rs*0.3)/TAU*47.0),0.5,bloom*0.16)
               * smoothstep(0.018,0.0,abs(r-0.805));
    col += C_GOLD * dots * 0.5;
  }
  {
    vec2 lp = polarTileLocal(p, 19.0, t*rs*0.5);
    float rune = glowLine(abs(r-0.72),0.0,bloom*0.32)*smoothstep(0.045,0.0,abs(lp.y));
    col += C_GOLD * rune * 0.55;
  }
  col += C_GOLD*(glowLine(r,0.66,bloom*0.45)+glowLine(r,0.635,bloom*0.28))*0.4;
  {
    float sp = glowLine(fract((a + t*rs*2.0)/TAU*29.0),0.5,bloom*0.4)
             * smoothstep(0.64,0.50,r)*smoothstep(0.50,0.56,r);
    col += mix(C_WHITE,C_GOLD,0.5)*sp*0.5;
  }
  {
    vec2 lp = polarTileLocal(p, 17.0, -t*rs*1.4);
    float rune = glowLine(abs(r-0.50),0.0,bloom*0.30)*smoothstep(0.05,0.0,abs(lp.y));
    col += C_VIOLET * rune * 0.6;
  }
  float br1 = 0.5+0.5*sin(t*1.7+1.0);
  col += C_VIOLET*(glowLine(r,0.40+0.01*br1,bloom*0.6)+glowLine(r,0.37,bloom*0.32))*0.5;
  {
    float sp = glowLine(fract((a - t*rs*4.4)/TAU*23.0),0.5,bloom*0.3)
             * smoothstep(0.38,0.28,r)*smoothstep(0.28,0.32,r);
    col += C_PINK*sp*0.45;
  }
  {
    float ca=cos(t*rs*0.4), sa=sin(t*rs*0.4);
    vec2 hp = mat2(ca,-sa,sa,ca)*p;
    float d = min(abs(sdEqTri(hp, 0.27)), abs(sdEqTri(-hp, 0.27)));
    float hex = glowLine(d, 0.0, bloom*0.20) * smoothstep(0.44,0.26,r);
    col += mix(C_VIOLET,C_GOLD,0.5) * hex * 0.5;
  }
  float core = 0.5+0.5*sin(t*2.3);
  col += C_WHITE*(0.045/(r+0.08))*(0.6+0.4*core);
  col += C_GOLD*glowLine(r,0.16,bloom*0.40)*0.40;
  col += C_ROSE*glowLine(r,0.22,bloom*0.28)*0.35;
  col *= smoothstep(1.32,0.06,r);
  return col;
}
vec4 frag () {
  vec2 p = uv0*2.0 - 1.0;
  float t = cc_time.x;
  vec3 col = scene(p, t);
  col = ACES(col * mainColor.a);
  col = mix(col, col*mainColor.rgb*1.4, 0.22);
  return vec4(col, 1.0);
}
layout(location = 0) out vec4 cc_FragColor;
void main() { cc_FragColor = frag(); }

